async function exportWav(){if(!clips.length)return toast('Add audio before exporting');toast('Rendering mix…');const sr=44100,len=Math.ceil(duration()*sr),off=new OfflineAudioContext(2,len,sr),anySolo=tracks.some(t=>t.solo);for(const t of tracks){const dest=chain(off,{...t,mute:t.mute||(anySolo&&!t.solo)},off.destination);for(const c of clips.filter(c=>c.trackId===t.id&&c.buffer)){const s=off.createBufferSource();s.buffer=c.buffer;s.connect(dest);s.playbackRate.value=c.rate||1;s.start(c.start,c.offset||0,c.duration*(c.rate||1))}}const rendered=await off.startRendering(),wav=encodeWav(rendered),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([wav],{type:'audio/wav'}));a.download=($('#projectName').value||'open-wave-mix')+'.wav';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('WAV exported')}
function encodeWav(b){const ch=b.numberOfChannels,len=b.length*ch*2,ab=new ArrayBuffer(44+len),v=new DataView(ab);const str=(o,s)=>[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+len,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,ch,true);v.setUint32(24,b.sampleRate,true);v.setUint32(28,b.sampleRate*ch*2,true);v.setUint16(32,ch*2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,len,true);let o=44;for(let i=0;i<b.length;i++)for(let c=0;c<ch;c++){let s=Math.max(-1,Math.min(1,b.getChannelData(c)[i]));v.setInt16(o,s<0?s*32768:s*32767,true);o+=2}return ab}
function noiseBuffer(ac,seconds=.25){const b=ac.createBuffer(1,Math.ceil(ac.sampleRate*seconds),ac.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;return b}
function triggerDrum(ac,type,time,dest){if(type===0){const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(150,time);o.frequency.exponentialRampToValueAtTime(42,time+.18);g.gain.setValueAtTime(1,time);g.gain.exponentialRampToValueAtTime(.001,time+.55);o.connect(g).connect(dest);o.start(time);o.stop(time+.6)}else if(type===1){const n=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain(),o=ac.createOscillator(),og=ac.createGain();n.buffer=noiseBuffer(ac,.22);f.type='highpass';f.frequency.value=1100;g.gain.setValueAtTime(.65,time);g.gain.exponentialRampToValueAtTime(.001,time+.2);n.connect(f).connect(g).connect(dest);o.type='triangle';o.frequency.value=180;og.gain.setValueAtTime(.35,time);og.gain.exponentialRampToValueAtTime(.001,time+.12);o.connect(og).connect(dest);n.start(time);o.start(time);o.stop(time+.15)}else if(type===2){for(const off of [0,.018,.038]){const n=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();n.buffer=noiseBuffer(ac,.12);f.type='bandpass';f.frequency.value=1400;f.Q.value=.7;g.gain.setValueAtTime(.45,time+off);g.gain.exponentialRampToValueAtTime(.001,time+off+.1);n.connect(f).connect(g).connect(dest);n.start(time+off)}}else{const n=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();n.buffer=noiseBuffer(ac,.08);f.type='highpass';f.frequency.value=6500;g.gain.setValueAtTime(.34,time);g.gain.exponentialRampToValueAtTime(.001,time+.07);n.connect(f).connect(g).connect(dest);n.start(time)}}
function renderBeatGrid(){const nums=$('#stepNumbers'),grid=$('#beatGrid');nums.innerHTML='';grid.innerHTML='';for(let i=0;i<16;i++){const n=document.createElement('span');n.textContent=i+1;nums.appendChild(n)}drumNames.forEach((name,row)=>{const label=document.createElement('div');label.className='drum-name';label.textContent=name;grid.appendChild(label);for(let step=0;step<16;step++){const b=document.createElement('button');b.className='step '+(step%4===0?'bar ':'')+(beatPattern[row][step]?'on':'');b.type='button';b.setAttribute('aria-label',`${name} step ${step+1}`);b.onclick=()=>{remember();beatPattern[row][step]=beatPattern[row][step]?0:1;b.classList.toggle('on');initAudio();triggerDrum(ctx,row,ctx.currentTime,ctx.destination)};grid.appendChild(b)}})}
function stopBeatPreview(){clearInterval(beatPreviewTimer);beatPreviewTimer=null;$('#previewBeatBtn').textContent='▶ Preview'}
function previewBeat(){if(beatPreviewTimer){stopBeatPreview();return}initAudio();let step=0;const stepMs=60000/Math.max(40,+$('#bpm').value)/4;const hit=()=>{drumNames.forEach((_,row)=>{if(beatPattern[row][step])triggerDrum(ctx,row,ctx.currentTime,ctx.destination)});step=(step+1)%16};hit();beatPreviewTimer=setInterval(hit,stepMs);$('#previewBeatBtn').textContent='■ Stop'}
async function addBeatToTimeline(){initAudio();const bpm=Math.max(40,+$('#bpm').value),seconds=60/bpm*4,off=new OfflineAudioContext(2,Math.ceil((seconds+.7)*44100),44100),master=off.createGain();master.gain.value=.82;master.connect(off.destination);for(let step=0;step<16;step++)drumNames.forEach((_,row)=>{if(beatPattern[row][step])triggerDrum(off,row,step*(seconds/16),master)});const rendered=await off.startRendering(),raw=encodeWav(rendered);remember();const t=makeTrack('808 Beat');clips.push({id:uid(),trackId:t.id,name:'808 Pattern',start:pausedAt,offset:0,duration:seconds,buffer:rendered,peaks:getPeaks(rendered),raw});selectedClip=clips.at(-1).id;markDirty();render();$('#beatDialog').close();toast('808 beat added to timeline')}
function wire(){makeTrack('Lead vocal');makeTrack('Instrument');$('#undoBtn').onclick=undo;$('#importBtn').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=e=>{if(e.target.files.length)remember();importFiles(e.target.files)};$('#addTrackBtn').onclick=()=>{remember();makeTrack()};$('#playBtn').onclick=play;$('#stopBtn').onclick=()=>stop(true);$('#recordBtn').onclick=record;$('#saveBtn').onclick=save;$('#loadBtn').onclick=showLoad;$('#exportBtn').onclick=exportWav;$('#splitBtn').onclick=split;$('#deleteBtn').onclick=deleteClip;$('#beatBtn').onclick=()=>{$('#beatDialog').showModal();renderBeatGrid()};$('#closeBeatBtn').onclick=()=>{stopBeatPreview();$('#beatDialog').close()};$('#previewBeatBtn').onclick=previewBeat;$('#clearBeatBtn').onclick=()=>{remember();beatPattern=drumNames.map(()=>Array(16).fill(0));renderBeatGrid()};$('#addBeatBtn').onclick=addBeatToTimeline;$('#newBtn').onclick=()=>{if(confirm('Start a new session? Unsaved changes will be lost.')){remember();stop(true);tracks=[];clips=[];loopStart=0;loopEnd=8;$('#projectName').value='Untitled session';makeTrack();updateLoopRegion()}};$('#zoomIn').onclick=()=>{zoom=Math.min(220,zoom+20);$('#zoomLabel').textContent=zoom+'%';render();updateLoopRegion()};$('#zoomOut').onclick=()=>{zoom=Math.max(40,zoom-20);$('#zoomLabel').textContent=zoom+'%';render();updateLoopRegion()};$('#projectName').oninput=markDirty;$('#bpm').oninput=markDirty;$('#metronome').onchange=()=>{if(playing){clearInterval(metroTimer);metroTimer=null;if($('#metronome').checked)startMetro()}};$('#loopToggle').onchange=()=>{remember();updateLoopRegion();markDirty();if(playing)restartAudio()};$('#loopInBtn').onclick=()=>{remember();loopStart=Math.min(pausedAt,loopEnd-.1);updateLoopRegion();markDirty();toast(`Loop starts at ${loopStart.toFixed(1)}s`)};$('#loopOutBtn').onclick=()=>{remember();loopEnd=Math.max(pausedAt,loopStart+.1);updateLoopRegion();markDirty();toast(`Loop ends at ${loopEnd.toFixed(1)}s`)};['filter','dist','wah','comp','delay','reverb'].forEach(id=>{$('#'+id+'On').onclick=e=>{const t=tracks.find(x=>x.id===selectedTrack);if(!t)return;remember();const next=e.currentTarget.getAttribute('aria-checked')!=='true';t[id+'On']=next;e.currentTarget.setAttribute('aria-checked',String(next));document.querySelector(`[data-effect="${id}"]`).dataset.enabled=String(next);markDirty();restartAudio();toast(`${id==='dist'?'Distortion':id==='comp'?'Compressor':id==='wah'?'Wah wah':id[0].toUpperCase()+id.slice(1)} ${next?'on':'off'}`)}});['filter','dist','wahDepth','wahRate','wahQ','threshold','ratio','attack','release','delay','reverb'].forEach(id=>{$('#'+id).onpointerdown=remember;$('#'+id).oninput=e=>{const t=tracks.find(x=>x.id===selectedTrack);if(t){t[id]=+e.target.value;syncFxLabels();markDirty()}};$('#'+id).onchange=restartAudio});$('#addPluginBtn').onclick=()=>{const t=tracks.find(x=>x.id===selectedTrack);if(!t)return toast('Select a track first');remember();(t.plugins||=[]).push({id:uid(),type:$('#pluginType').value,enabled:true});renderPlugins();markDirty();restartAudio();toast('Plugin added')};$('.timeline-wrap').onpointerdown=e=>{if(e.button!==0||e.target.closest('.clip'))return;closeClipContextMenu();seekTimeline(e.clientX)};$('#contextSplit').onclick=()=>{closeClipContextMenu();split()};$('#contextDuplicate').onclick=()=>{closeClipContextMenu();duplicateClip()};$('#contextDelete').onclick=()=>{closeClipContextMenu();deleteClip()};document.addEventListener('pointerdown',e=>{if(!e.target.closest('#clipContextMenu'))closeClipContextMenu()});document.onkeydown=e=>{if(e.key==='Escape')closeClipContextMenu();if(e.target.matches('input,select'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();return}if(e.code==='Space'){e.preventDefault();play()}if(e.key==='Delete')deleteClip()};renderBeatGrid();updateLoopRegion();window.addEventListener('beforeunload',()=>{stopBeatPreview();stop()});}
